// Agregações vêm prontas do SQL (nó "Consultar KPIs (SQL)"). Aqui: índices, formatação pt-BR
// (o pacote enviado à IA só tem valores prontos para citar) e a lista de números permitidos na narrativa.
const r = $input.first().json;
const periodo = $('Definir período').first().json;
const ini = DateTime.fromISO(periodo.periodoInicio);
const fim = DateTime.fromISO(periodo.periodoFim);
const dias = Number(r.dias);
const iniAnt = ini.minus({ days: dias });
const fimAnt = ini.minus({ days: 1 });

const agregar = g => {
  const a = {
    inspecoes: Number(g?.inspecoes ?? 0), analisadas: Number(g?.analisadas ?? 0), avaria: Number(g?.avaria ?? 0),
    bruta: Number(g?.bruta ?? 0), desconto: Number(g?.desconto ?? 0),
  };
  a.indice = a.analisadas ? a.avaria / a.analisadas * 100 : 0;
  a.final = a.bruta - a.desconto;
  return a;
};
const tot = agregar(r.totais);
const totAnt = agregar(r.anterior);
const porContrato = (r.por_contrato || []).map(g => ({ chave: g.chave, alerta: g.alerta === true, ...agregar(g) }));
const porFornecedor = (r.por_fornecedor || []).map(g => ({ chave: g.chave, ...agregar(g) }));
const alertas = porContrato.filter(c => c.alerta);

const n0 = v => v.toLocaleString('pt-BR', { maximumFractionDigits: 0 });
const pct = v => v.toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
const pp = v => (v >= 0 ? '+' : '-') + Math.abs(v).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' p.p.';
const brl = v => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const fmt = a => ({
  inspecoes: n0(a.inspecoes), pranchasAnalisadas: n0(a.analisadas), pranchasComAvaria: n0(a.avaria),
  indicePerdas: pct(a.indice), indenizacaoBruta: brl(a.bruta), descontos: brl(a.desconto), indenizacaoFinal: brl(a.final),
});
const fmtGrupo = g => ({ nome: g.chave, ...fmt(g) });

const kpis = {
  periodo: { inicio: ini.toFormat('dd/MM/yyyy'), fim: fim.toFormat('dd/MM/yyyy'), dias: n0(dias) },
  totais: fmt(tot),
  periodoAnterior: { inicio: iniAnt.toFormat('dd/MM/yyyy'), fim: fimAnt.toFormat('dd/MM/yyyy'), ...fmt(totAnt) },
  variacao: {
    indicePerdas: totAnt.inspecoes ? pp(tot.indice - totAnt.indice) : 'sem base de comparação',
    indenizacaoFinal: totAnt.final ? pct((tot.final - totAnt.final) / Math.abs(totAnt.final) * 100) : 'sem base de comparação',
  },
  contagens: { contratos: n0(porContrato.length), fornecedores: n0(porFornecedor.length), contratosEmAlerta: n0(alertas.length), registrosIgnorados: n0(Number(r.ignorados ?? 0)) },
  porContrato: porContrato.slice(0, 10).map(fmtGrupo),
  porFornecedor: porFornecedor.slice(0, 10).map(fmtGrupo),
  contratosEmAlerta: alertas.map(fmtGrupo),
  serieSemanal: (r.serie_semanal || []).map(s => ({ semana: s.semana, ...fmt(agregar(s)) })),
  criterioAlerta: 'contrato com pelo menos 50 pranchas analisadas e índice de perdas igual ou maior que o dobro do índice geral',
};

// Números permitidos na narrativa: todo número que aparece no pacote, normalizado (pt-BR -> valor)
const normalizar = t => String(Math.round(Number(t.replace(/\./g, '').replace(',', '.')) * 100) / 100);
const permitidos = new Set();
const coletar = v => {
  if (v && typeof v === 'object') return Object.values(v).forEach(coletar);
  for (const t of String(v).match(/\d+(?:[.,]\d+)*/g) || []) permitidos.add(normalizar(t));
};
coletar(kpis);

return [{ json: { semDados: tot.inspecoes === 0, kpis, numerosPermitidos: [...permitidos] } }];

