={{ (() => {
  const r = $('Gerar narrativa').first().json
  // A resposta pode vir como texto consolidado ou como lista de partes de conteúdo
  const texto = r.merged_response ?? (Array.isArray(r.content) ? r.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : (r.text ?? ''))
  return texto.trim()
})() }}

={{ (() => {
  const r = $('Gerar narrativa').first().json
  // A resposta pode vir como texto consolidado ou como lista de partes de conteúdo
  const texto = r.merged_response ?? (Array.isArray(r.content) ? r.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : (r.text ?? ''))
  const permitidos = new Set($('Calcular KPIs').first().json.numerosPermitidos)
  // Mesmo normalizador do cálculo: tira separador de milhar, vírgula vira ponto
  const normalizar = t => String(Math.round(Number(t.replace(/\./g, '').replace(',', '.')) * 100) / 100)
  const citados = texto.match(/\d+(?:[.,]\d+)*/g) || []
  return [...new Set(citados.filter(t => !permitidos.has(normalizar(t))))]
})() }}

={{ (() => {
  const e = $('Gerar narrativa').first().json.error
  // O nó devolve o erro como texto ou como objeto, conforme a falha
  return !e ? '' : (typeof e === 'string' ? e : (e.message ?? JSON.stringify(e)))
})() }}

={{ (() => {
  const v = $('Validar narrativa')
  if (!v.isExecuted) return ''
  const r = v.first().json
  // Só publica texto sem erro de API e sem número inventado
  return !r.erroApi && r.narrativaBruta && r.numerosNaoEncontrados.length === 0 ? r.narrativaBruta : ''
})() }}

={{ (() => {
  const v = $('Validar narrativa')
  if (!v.isExecuted) return 'Sem inspeções no período: narrativa não gerada'
  const r = v.first().json
  if (r.erroApi) return ('Falha na API Claude: ' + r.erroApi).slice(0, 300)
  if (!r.narrativaBruta) return 'API Claude devolveu texto vazio'
  if (r.numerosNaoEncontrados.length) return 'Narrativa descartada: números fora dos KPIs (' + r.numerosNaoEncontrados.join(', ') + ')'
  return 'OK'
})() }}
